<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['Student']);
$user=current_user();$st=$pdo->prepare('SELECT s.* FROM students s WHERE s.user_id=?');$st->execute([$user['id']]);$student=$st->fetch();
$req=$pdo->prepare('SELECT * FROM clearance_requests WHERE student_id=? ORDER BY submitted_at DESC');$req->execute([$student['id']]);$requests=$req->fetchAll();
$pageTitle='Clearance Status | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Student</span></div><div class="avatar"><?=e(strtoupper(substr($user['name'],0,2)))?></div></header><div class="content"><div class="page-header"><div><p>TRACKING</p><h1>Department Clearance Status</h1></div></div>
<?php foreach($requests as $r):$dc=$pdo->prepare('SELECT dc.*,d.name FROM department_clearances dc JOIN departments d ON d.id=dc.department_id WHERE dc.request_id=? ORDER BY d.name');$dc->execute([$r['id']]);$clearances=$dc->fetchAll();$approved=0;foreach($clearances as $c){if($c['status']==='Approved')$approved++;}$pct=count($clearances)?round($approved*100/count($clearances)):0;?>
<section class="panel"><div class="panel-header"><h2>Semester <?=e($r['semester'])?> <span class="status <?=strtolower(str_replace(' ','-',e($r['status'])))?>" style="margin-left:8px"><?=e($r['status'])?></span></h2><b><?=$pct?>%</b></div><div class="progress-bar"><span style="width:<?=$pct?>%"></span></div><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Department</th><th>Status</th><th>Remarks</th><th>Updated</th></tr></thead><tbody><?php foreach($clearances as $c):?><tr><td><?=e($c['name'])?></td><td><b class="status <?=strtolower(e($c['status']))?>"><?=e($c['status'])?></b></td><td><?=e($c['remarks'] ?: '—')?></td><td><?=e($c['updated_at']?date('d M Y',strtotime($c['updated_at'])):'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if($r['status']==='Approved'):?><a class="btn btn-primary" style="margin-top:14px" href="certificate.php?id=<?=(int)$r['id']?>"><i class="fa-solid fa-download"></i> View Certificate</a><?php endif;?></section>
<?php endforeach;if(!$requests):?><div class="panel"><p>No clearance requests found.</p></div><?php endif;?></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
